const { exec } = require('child_process');

// Dosya yolu
const scriptPath = "C:\\VibeBot\\main.py";

// Telegram verileri
const message = $input.item.json.message?.text || "";
const chatId = $input.item.json.message?.chat?.id || "";

// Komut
const command = `python "${scriptPath}" "${message}" "${chatId}"`;

return new Promise((resolve, reject) => {
  // maxBuffer: Hafıza limitini 10MB'a çıkarır (Büyük çıktılar için şart)
  exec(command, { maxBuffer: 1024 * 1024 * 10 }, (error, stdout, stderr) => {

    // Çıktıyı temizle
    const outputText = stdout.trim();

    // JSON'u cımbızla çek al
    const jsonMatch = outputText.match(/\{.*"durum":.*"basarili".*\}/s);
    const errorMatch = outputText.match(/\{.*"durum":.*"hata".*\}/s);

    if (jsonMatch) {
      try {
        const cleanData = JSON.parse(jsonMatch[0]);
        resolve([{ json: cleanData }]);
      } catch (e) {
        resolve([{ json: { error: "JSON bozuk", raw: outputText } }]);
      }
    } else if (errorMatch) {
        // Python içinden gelen kontrollü hatayı yakala
        try {
            const errData = JSON.parse(errorMatch[0]);
            resolve([{ json: { error: errData.mesaj, raw: outputText } }]);
        } catch(e) {
            resolve([{ json: { error: "Bilinmeyen Hata", raw: outputText } }]);
        }
    } else {
      // Hiçbir şey bulamazsa ham veriyi göster (Hata ayıklamak için)
      console.log("Python Çıktısı:", outputText);
      console.log("Python Hatası:", stderr);
      resolve([{ json: { error: "JSON bulunamadı", raw: outputText, stderr: stderr } }]);
    }
  });
});
